// Test behaviour from the Settings page (sim_person_behaviour): answer (AI picks), fastest, cheapest, balanced, decline, unclear, silent.
const snap = (() => { try { const r = $('Context').first().json; return typeof r.context === 'string' ? JSON.parse(r.context) : (r.context || {}); } catch { return {}; } })();
const NAMES = { buyer: snap.customer?.name || 'the buyer', delivery_contact: snap.delivery_contact?.name || 'the delivery contact', driver: (snap.assignments || []).find((a) => a.driver)?.driver || 'the driver', staff: 'Bahn staff' };
const ROLE = { buyer: 'Buyer', delivery_contact: 'Delivery contact', driver: 'Driver', staff: 'Staff' };
const i = $('Start').first().json, role = i.role;
const S = Object.fromEntries($('Settings').all().map((r) => [r.json.key, r.json.value]));
const mode = String(S.sim_person_behaviour || 'answer').trim();
if (mode === 'silent') return [];
let buttons = []; try { buttons = JSON.parse(i.buttons || '[]'); } catch {}
const pick = ['fastest', 'cheapest', 'balanced'].includes(mode) ? buttons.find((b) => String(b.label).toLowerCase().includes(mode))?.key : mode === 'decline' ? 'decline' : '';
const facts = { order: i.order_ref, you: { role, name: NAMES[role] }, car: snap.vehicle || snap.order?.vehicle, delivery: snap.delivery_window || snap.order?.delivery_window, delivery_contact: snap.delivery_contact, buyer: snap.customer?.name };
const prompt = `You play ${NAMES[role]}, the ${role === 'buyer' ? 'buyer (paying customer)' : 'person receiving the car at the delivery address'} of a car delivery by Bahn Express, in a test. FACTS (only use these): ${JSON.stringify(facts).slice(0, 2500)}
Bahn Express just wrote to you:
"""${i.text}"""
${buttons.length ? `You can tap one of these buttons: ${buttons.map((b) => `${b.key} = ${b.label}`).join('; ')}.` : ''}
${pick ? `You choose ${pick === 'decline' ? 'to decline' : 'button ' + pick}.` : mode === 'unclear' ? 'Answer vaguely: do not choose anything clearly, ask something unrelated or hesitate.' : buttons.length ? 'Choose what a real person in your role would most likely choose.' : 'Answer naturally; confirm if the message asks you to confirm and nothing in the FACTS is against it.'}
Reply in 1-2 short sentences in English. Answer ONLY with JSON: {"text": "<your reply>", "choice": "<button key you tap, or empty>"}`;
return [{ json: { prompt, pick, mode, buttons, name: NAMES[role] } }];

